// Handler calls from the SDL function
void testfunction_PI_protected_if(const asn1SccMyInteger *IN_counter)
{
    char aMsgBuff[100];
    unsigned long ulCurrentTimeNs = Hal_GetElapsedTimeInNs();

    // Have we already had a call? If so determine the elapsed time
    if (iNumberOfInvocations == 0)
    {
        sprintf(aMsgBuff, "SDL function invoked the testfunction. Call 0. Time: %lu ms", ulCurrentTimeNs / 1000000);
        transmit_log_info(aMsgBuff);
    }
    else if (iNumberOfInvocations == 1)
    {
        ulElapsedTimeMs = (ulCurrentTimeNs - ulLastInvocationTimeNs) / 1000000;
        sprintf(aMsgBuff, "SDL function invoked the testfunction. Call #%i. Interval since last call: %lu ms", iNumberOfInvocations+1, ulElapsedTimeMs);
        transmit_log_info(aMsgBuff);

        // If time is within range the SDL function must be working
        bTestPass = ulElapsedTimeMs > TIMER_INTERVAL_MIN && ulElapsedTimeMs < TIMER_INTERVAL_MAX;
    }

    // Increment count of invocations
    iNumberOfInvocations++;

    // Make a note of the last time we were called
    ulLastInvocationTimeNs = ulCurrentTimeNs;
}

